import{groundHeight}from'./world.js?v=balance-8';
import{fractureVoxels,fractureCells}from'./fracture.js?v=balance-8';
import{VoxelPart}from'./voxels.js?v=balance-8';
const B=globalThis.BABYLON,V=B.Vector3,clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export class CrashSequence{
 constructor(scene,effects,world=null,traffic=null){this.scene=scene;this.effects=effects;this.world=world;this.traffic=traffic;this.pieces=[];this.center=V.Zero();this.impactPoint=V.Zero();this.time=0;this.smokeTimer=0;this.radius=12;this.secondaryCraters=0;this.lastGroundEffect=0;}
 addPiece(mesh,velocity,{heavy=false,smoking=false,focus=false,material='metal',count=0}={}){mesh.computeWorldMatrix(true);const bb=mesh.getBoundingInfo().boundingBox.extendSizeWorld,radius=clamp(Math.min(bb.x,bb.y,bb.z),.1,2);const p={mesh,velocity,spin:new V((Math.random()-.5)*5,(Math.random()-.5)*5,(Math.random()-.5)*5),radius,heavy,smoking,focus,material,count,struck:false};this.pieces.push(p);return p;}
 start(plane,velocity,impact=null,fuel=100){this.clear();this.effects.clear();this.time=0;this.smokeTimer=0;this.radius=12;this.secondaryCraters=0;this.center.copyFrom(plane.root.position);this.impactPoint.copyFrom(impact?.point||plane.root.position);this.fuel=fuel;this.energy=velocity.length();plane.root.computeWorldMatrix(true);const collected=[],surface=groundHeight(this.impactPoint.x,this.impactPoint.z),groundImpact=this.impactPoint.y<Math.max(0,surface)+8;
  for(const p of plane.parts){if(p.spent)continue;const mesh=p.mesh;mesh.isVisible=true;mesh.visibility=1;mesh.setEnabled(true);mesh.computeWorldMatrix(true);const matrix=mesh.getWorldMatrix().clone(),center=mesh.getBoundingInfo().boundingBox.center.clone(),scale=V.One(),q=B.Quaternion.Identity(),pos=V.Zero();matrix.decompose(scale,q,pos);collected.push({p,mesh,center,absolute:V.TransformCoordinates(center,matrix),scale,q});}
  for(const{p,mesh,center,absolute,scale,q}of collected){mesh.parent=null;mesh.bakeTransformIntoVertices(B.Matrix.Translation(-center.x,-center.y,-center.z));mesh.position.copyFrom(absolute);mesh.scaling.copyFrom(scale);mesh.rotationQuaternion=q;const radial=absolute.subtract(this.center).add(new V((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3)).normalize(),heavy=p.count>15000,v=velocity.scale(groundImpact?(heavy?.34:.23):(heavy?.62:.44)).add(radial.scale(heavy?10:18+Math.random()*17));v.y=Math.max(v.y,0)+7+Math.random()*12;this.addPiece(mesh,v,{heavy,smoking:heavy||/engine|cowling|nacelle/.test(p.name),focus:true,count:p.count});}
  plane.root.dispose(false,false);if(impact)this.breakTarget(impact,velocity);if(groundImpact&&surface>=0)this.makeCrater(this.impactPoint,clamp(6+this.energy*.035+fuel*.018,8,23),clamp(2+this.energy*.018,3,9),velocity);
  this.effects.explosion(this.impactPoint,{fuel,energy:this.energy,ground:groundImpact,water:impact?.kind==='water'});return this.pieces.length;
 }
 breakTarget(impact,velocity){if(!this.world||!this.traffic)return;let meshes=[],inherited=V.Zero(),material='masonry';if(impact.kind==='scenery'||impact.kind==='cable'){const owner=impact.target?.owner;if(!owner||!this.world.removeOwner(owner))return;meshes=owner.meshes||[owner.mesh];material=/oak|pine|birch|palm|cactus|house|barn|cottage/.test(owner.name)?'wood':/pylon|cable|truck/.test(owner.name)?'metal':'masonry';}
  else if(impact.kind==='bird'||impact.kind==='aircraft'){const target=this.traffic.detachTarget(impact.target);if(!target)return;meshes=target.meshes;inherited=target.velocity;material=impact.kind==='bird'?'feather':'metal';}
  for(const mesh of meshes){if(!mesh||mesh.isDisposed())continue;const fragments=fractureVoxels(mesh,this.scene);for(const f of fragments){const radial=f.mesh.position.subtract(this.impactPoint).add(new V((Math.random()-.5)*2,1,(Math.random()-.5)*2)).normalize(),v=inherited.scale(.7).add(velocity.scale(material==='feather'?.12:.065)).add(radial.scale(material==='feather'?10:12+Math.random()*18));v.y+=5+Math.random()*8;this.addPiece(f.mesh,v,{material,count:f.count,smoking:material==='metal'&&impact.kind==='aircraft'&&f.count>2500});}mesh.dispose(false,false);}
  if(impact.kind==='bird'||impact.kind==='aircraft')impact.target.root.dispose(false,false);
 }
 makeCrater(point,radius,depth,velocity=V.Zero()){if(!this.world)return;const crater=this.world.excavate(point,radius,depth);if(!crater)return;for(const cut of crater.ejecta)for(const f of fractureCells(cut.cells,cut.size,cut.matrix,cut.name,this.scene)){const radial=f.mesh.position.subtract(point).add(new V(0,2,0)).normalize(),v=radial.scale(8+Math.random()*15).add(velocity.scale(.07));v.y+=7+Math.random()*9;this.addPiece(f.mesh,v,{material:'masonry',count:f.count});}const rnd=Math.random,count=Math.min(90,Math.floor(radius*4));for(let i=0;i<count;i++){const angle=rnd()*Math.PI*2,d=Math.sqrt(rnd())*radius*.9,x=point.x+Math.cos(angle)*d,z=point.z+Math.sin(angle)*d,size=.45+rnd()*.7,part=new VoxelPart('excavated earth',this.scene,null,size),n=1+Math.floor(rnd()*2);part.box(0,0,0,size*n,size*n,size*n,i%4===0?'#4a4037':'#806750');if(i%3===0)part.box(size,0,0,size,size,size,'#655442');part.build();part.mesh.parent=null;part.node.dispose(false,false);part.mesh.position.set(x,Math.max(point.y,groundHeight(x,z))+rnd()*2,z);const v=new V(Math.cos(angle)*(7+rnd()*15),9+rnd()*20,Math.sin(angle)*(7+rnd()*15)).add(velocity.scale(.055));this.addPiece(part.mesh,v,{material:'earth',count:part.count});}
 }
 update(dt){this.time+=dt;this.smokeTimer+=dt;this.lastGroundEffect-=dt;let sum=this.impactPoint.scale(this.time<3?6:2),weights=this.time<3?6:2;const emitSmoke=this.smokeTimer>.08;for(const p of this.pieces){const drag=p.material==='feather'?1.8:p.material==='earth'?.4:.14;p.velocity.y-=9.81*dt;p.velocity.scaleInPlace(Math.exp(-dt*drag));p.mesh.position.addInPlace(p.velocity.scale(dt));p.mesh.rotationQuaternion??=B.Quaternion.Identity();p.mesh.rotationQuaternion=p.mesh.rotationQuaternion.multiply(B.Quaternion.RotationYawPitchRoll(p.spin.y*dt,p.spin.x*dt,p.spin.z*dt));p.mesh.rotationQuaternion.normalize();const h=groundHeight(p.mesh.position.x,p.mesh.position.z),ground=Math.max(0,h)+p.radius;
   if(p.mesh.position.y<ground){const speed=p.velocity.length(),sink=Math.abs(p.velocity.y),point=new V(p.mesh.position.x,Math.max(0,h),p.mesh.position.z);p.mesh.position.y=ground;p.velocity.y=Math.abs(p.velocity.y)*(p.material==='earth'?.13:.24);p.velocity.x*=h<0?.42:.76;p.velocity.z*=h<0?.42:.76;p.spin.scaleInPlace(.72);if(!p.struck&&speed>12){p.struck=true;if(p.focus&&p.heavy&&this.secondaryCraters<2&&h>=0&&sink>10){this.secondaryCraters++;this.makeCrater(point,4+Math.min(3,speed*.012),1.5+Math.min(2,sink*.045),p.velocity);}if(p.focus||this.lastGroundEffect<=0){this.effects.impactBurst(point,p.velocity,{water:h<0,metal:p.material==='metal',energy:speed});this.lastGroundEffect=.09;}}else if(p.focus&&speed>15&&this.lastGroundEffect<=0){this.effects.impactBurst(point,p.velocity,{water:h<0,metal:true,energy:speed,small:true});this.lastGroundEffect=.12;}if(speed<1)p.velocity.setAll(0);}
   if(p.focus){const w=p.heavy?5:1;sum.addInPlace(p.mesh.position.scale(w));weights+=w;}if(p.smoking&&emitSmoke)this.effects.wreckSmoke(p.mesh.position,p.velocity,this.time,this.fuel);
  }if(weights)this.center.copyFrom(sum.scale(1/weights));this.radius=Math.max(12,V.Distance(this.impactPoint,this.center)+12);for(const p of this.pieces)if(p.focus)this.radius=Math.max(this.radius,V.Distance(p.mesh.position,this.center)+6);if(emitSmoke)this.smokeTimer=0;
 }
 clear(){for(const p of this.pieces)p.mesh.dispose(false,false);this.pieces=[];}
}
